@pytest.fixture
def status_stats_data(db):
    ds = []
    for i, status in enumerate([Dataset.HAS_DATA, Dataset.INVENTORED, Dataset.PLANNED, Dataset.UNASSIGNED]):
        # published is pinned because commentless datasets are counted in the
        # status chart at their published date
        d = DatasetFactory(
            status=status,
            slug=f"ds-char-{i}",
            published=datetime(2022, 12, 28, 10, 0, 0, tzinfo=timezone.utc),
        )
        DatasetStatsFactory(
            dataset_id=d.pk,
            created=date(2022, 12, 28),
            object_count=10 + i,
            maturity_level=(i % 5) + 1,
        )
        DatasetStatsFactory(
            dataset_id=d.pk,
            created=date(2023, 1, 3),
            object_count=20 + i,
            maturity_level=(i % 5) + 1,
        )
        ds.append(d)
    return ds


@pytest.mark.haystack
@pytest.mark.django_db
@pytest.mark.parametrize("duration", DURATIONS)
@pytest.mark.parametrize("indicator", ["dataset-count", "object-count", "level-average"])
def test_status_stats_snapshot(app: DjangoTestApp, status_stats_data, duration, indicator):
    with freeze_time(FROZEN_NOW):
        resp = app.get(reverse("dataset-stats-status"), params={"indicator": indicator, "duration": duration})
    assert resp.status_code == 200
    snapshot = {
        "time_chart_data": json.dumps(resp.context["time_chart_data"]),
        "bar_chart_data": [
            {"display_value": str(b.get("display_value")), "count": b.get("count")}
            for b in resp.context["bar_chart_data"]
        ],
        "max_count": resp.context["max_count"],
    }
    assert snapshot == EXPECTED[(indicator, duration)]
